<script setup lang="ts">
import {ref,onUnmounted} from 'vue';import axios from 'axios';
const props=defineProps<{placeId:number;parentId?:number;replyName?:string}>();const emit=defineEmits<{saved:[];cancel:[]}>();
const content=ref(''),file=ref<File|null>(null),error=ref(''),busy=ref(false),preview=ref(''),inputKey=ref(0);let objectUrl='';
function choose(e:Event){if(objectUrl)URL.revokeObjectURL(objectUrl);file.value=(e.target as HTMLInputElement).files?.[0]||null;objectUrl=file.value?URL.createObjectURL(file.value):'';preview.value=objectUrl;}
onUnmounted(()=>{if(objectUrl)URL.revokeObjectURL(objectUrl);});
async function send(){busy.value=true;error.value='';try{const token=(await axios.get('/api/auth/csrf')).data.token;const body=new FormData();body.append('message',new Blob([JSON.stringify({placeId:props.placeId,parentId:props.parentId||null,content:content.value})],{type:'application/json'}));if(file.value)body.append('file',file.value);await axios.post('/api/conversations',body,{headers:{'X-XSRF-TOKEN':token}});content.value='';file.value=null;preview.value='';if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl='';inputKey.value++;emit('saved');}catch{error.value='发送失败，请检查图片格式或稍后重试';}finally{busy.value=false;}}
</script>
<template><form class="composer" @submit.prevent="send"><label>{{parentId?'回复 @'+replyName:'发布问题或分享'}}<textarea v-model="content" maxlength="1000" :placeholder="parentId?'写下你的回复…':'分享这里的问题与经验…'"></textarea></label><div class="emoji"><button v-for="emoji in ['😊','👍','❤️','😂','🎉','🤔','🙏','😭']" :key="emoji" type="button" @click="content+=emoji">{{emoji}}</button></div><label class="attachment">图片 / 表情包<input :key="inputKey" type="file" accept="image/png,image/jpeg,image/gif" @change="choose"></label><img v-if="preview" class="preview" :src="preview" alt="待发送图片预览"><small>发言图片缩略显示，点击可看原图；支持PNG、JPEG、GIF。</small><p role="alert">{{error}}</p><button class="send" :disabled="busy||(!content.trim()&&!file)">{{busy?'发送中…':'发送'}}</button><button v-if="parentId" type="button" class="cancel" :disabled="busy" @click="$emit('cancel')">取消回复</button></form></template>
<style scoped>.composer{padding:18px;background:#faf7ef;border:1px solid #e8e2d5;border-radius:10px;margin:18px 0}label{font-size:13px;color:#304b49}textarea{display:block;width:100%;min-height:85px;border:1px solid #d9dece;border-radius:6px;padding:12px;font:inherit;margin:10px 0}.emoji{display:flex;gap:8px;flex-wrap:wrap}.emoji button{border:0;background:none;padding:4px;cursor:pointer;font-size:19px}.attachment{display:block;margin:10px 0;font-size:11px}.attachment input{display:block;margin-top:7px;max-width:100%;font-size:11px}.preview{display:block;max-width:180px;max-height:140px;object-fit:contain}small{display:block;color:#8a8d7a;font-size:10px;margin:10px 0}.send{border:0;border-radius:5px;padding:10px 24px;background:#304b49;color:white;cursor:pointer}.cancel{border:0;background:none;color:#96764e;padding:10px;cursor:pointer}button:disabled{opacity:.5}p{font-size:12px;color:#a34b40}</style>
